from pathlib import Path
import json,subprocess,sys,hashlib,base64,html,collections
R=Path.cwd();D=R/'build/winner-music';O=D/'clips';O.mkdir(exist_ok=True);sys.path.insert(0,str(R/'build/audio-tools'));import imageio_ffmpeg
rows=json.loads((D/'source-manifest.json').read_text(encoding='utf8'));assert len(rows)==7
cuts={'zarathustra':{'short':(71,83),'long':(59,83)},'te-deum':{'short':(0,12),'long':(0,24)},'fireworks':{'short':(0,12),'long':(0,24)},'aida':{'short':(0,12),'long':(0,24)},'pomp':{'short':(280,292),'long':(280,304)},'kiev':{'short':(0,12),'long':(0,24)},'william-tell':{'short':(450,462),'long':(450,474)}}
transcodes=json.loads((D/'official-transcodes.json').read_text(encoding='utf8'))
for r in rows:
 if r['id'] in ['kiev','william-tell']:
  p=next(p for p in transcodes['query']['pages'].values() if p['title']==r['sourceTitle']);r['originalDownloadUrl']=r['downloadUrl'];r['downloadUrl']=next(d['src'] for d in p['videoinfo'][0]['derivatives'] if d.get('transcodekey')=='mp3')
 r['variants']=[]
 if r['id']=='te-deum':r['mood']='Cérémoniel et royal — version pour orgue.';r['recordingNote']='Version pour orgue : Ian Dollins.'
 elif r['id']=='fireworks':r['credit']='St Matthew Concert Choir / Paul Ayres (recording metadata)';r['recordingNote']='Version indiquée dans les métadonnées : St Matthew Concert Choir / Paul Ayres.'
 elif r['id']=='kiev':r['credit']='Enregistrement diffusé par Musopen ; interprète non précisé dans la fiche source.';r['recordingNote']='Enregistrement Musopen ; interprète non précisé dans la fiche source.'
 else:r['recordingNote']=r['credit']
 for kind,(start,end) in cuts[r['id']].items():
  wav=O/(r['id']+'-'+kind+'.wav');mp3=wav.with_suffix('.mp3');duration=end-start
  filters=f'atrim=start={start}:end={end},asetpts=PTS-STARTPTS,loudnorm=I=-18:TP=-2:LRA=9,afade=t=in:d=0.04,afade=t=out:st={duration-.8}:d=0.8'
  subprocess.run([imageio_ffmpeg.get_ffmpeg_exe(),'-hide_banner','-loglevel','error','-y','-i',str(D/'sources'/(r['id']+'.source')),'-af',filters,'-ar','44100','-ac','2','-c:a','pcm_s16le',str(wav)],check=True,capture_output=True)
  subprocess.run([imageio_ffmpeg.get_ffmpeg_exe(),'-hide_banner','-loglevel','error','-y','-i',str(wav),'-c:a','libmp3lame','-b:a','160k',str(mp3)],check=True,capture_output=True)
  r['variants'].append(dict(kind=kind,file='clips/'+mp3.name,wavFile='clips/'+wav.name,startSeconds=start,endSeconds=end,durationSeconds=duration,sha256=hashlib.sha256(mp3.read_bytes()).hexdigest(),changes='Excerpt, stereo 44.1 kHz, loudness normalized to -18 LUFS / -2 dBTP, 40 ms fade-in and 800 ms fade-out; MP3 160 kbps.'))
 print('Prepared',r['id'],flush=True)
(R/'audio-bank/winner-music-sampler.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf8');(D/'sampler.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf8')
css='''*{box-sizing:border-box}body{margin:0;background:#0e1521;color:#edf1f8;font:18px/1.5 system-ui}main{max-width:1140px;margin:auto;padding:32px 22px}h1{font-size:clamp(28px,5vw,44px);line-height:1.15;margin:8px 0 16px}.intro{max-width:760px;color:#becadb}.eyebrow{color:#e9bc62;font-size:13px;letter-spacing:.14em;text-transform:uppercase}.podium{border:1px solid #a78242;border-radius:20px;background:radial-gradient(ellipse at top,#514027 0,#1d2636 65%);text-align:center;padding:32px 20px;margin:26px 0;min-height:240px}.winner{font-weight:800;color:#ffdb91;font-size:clamp(30px,5vw,56px);margin:22px 0 30px;line-height:1.2}.controls{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:20px 0}button,select,input{font:inherit;border:1px solid #586a82;border-radius:9px;padding:10px 14px;background:#25364f;color:#fff}button{cursor:pointer}button:hover,button:focus-visible{background:#395174;outline:2px solid #d6b363;outline-offset:2px}.primary{background:#e4b75e;color:#1a1721;border-color:#e4b75e;font-weight:700}.primary:hover{background:#f9d087}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:18px}article{border:1px solid #35445d;border-radius:15px;padding:22px;background:#19253a;min-width:0}article.active{border-color:#edc273;box-shadow:0 0 0 2px #ad7d35}h2{font-size:23px;line-height:1.25;margin:8px 0 12px}.composer{color:#d9b977}.mood{color:#c8d2df;min-height:54px}.plays{display:flex;gap:9px;flex-wrap:wrap}audio{width:100%;margin-top:16px}.small,details{font-size:14px;color:#b9c6d8}details{margin-top:18px;overflow-wrap:anywhere}a{color:#a4d5ff}summary{cursor:pointer}#now{min-height:27px;color:#d6e2f2}.name{max-width:210px}progress{width:100%;accent-color:#edc273;height:7px}.vote{margin-top:16px;width:100%}.voted{background:#775a28}.hint{font-size:15px;color:#c1ccdc}footer{padding:25px 0;color:#b9c6d8;font-size:14px}@media(prefers-reduced-motion:no-preference){.podium.playing .winner{animation:reveal .6s ease-out}@keyframes reveal{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}}'''
page='<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>La musique du grand gagnant — TriviaParty</title><style>'+css+'</style><main><div class="eyebrow">TriviaParty · sélection musicale</div><h1>La musique du grand gagnant</h1><p class="intro">Sept façons de célébrer la victoire. Comparez une fanfare courte de 12 secondes et une célébration de 24 secondes, avec un volume comparable.</p><section class="podium" id="podium"><div class="eyebrow">Fin de partie</div><div class="winner" id="winner">Gagnant : Camille</div><div id="now" role="status" aria-live="polite">Choisissez un morceau ci-dessous.</div><progress id="progress" max="1" value="0" aria-label="Progression du morceau"></progress></section><div class="controls"><label>Gagnant <input class="name" id="name" value="Camille" maxlength="35"></label><label><input id="tie" type="checkbox"> Égalité avec Alex</label></div><div class="controls"><label>Écoute enchaînée <select id="length"><option value="short">Versions de 12 s</option><option value="long">Versions de 24 s</option></select></label><button id="all" class="primary">Tout écouter</button><button id="stop">Arrêter</button></div><p class="hint">Une seule piste joue à la fois. Les étoiles vous permettent de noter vos favoris sur cet appareil.</p><section class="grid">'
for n,r in enumerate(rows,1):
 page+=f'<article id="card-{r["id"]}"><div class="composer">{n:02d} · {html.escape(r["composer"])}</div><h2>{html.escape(r["title"])}</h2><p class="mood">{html.escape(r["mood"])}</p><div class="plays"><button data-id="{r["id"]}" data-kind="short">Écouter · 12 s</button><button data-id="{r["id"]}" data-kind="long">Écouter · 24 s</button></div>'
 for v in r['variants']:
  encoded=base64.b64encode((D/v['file']).read_bytes()).decode();page+=f'<audio id="audio-{r["id"]}-{v["kind"]}" preload="none" src="data:audio/mpeg;base64,{encoded}"></audio>'
 page+=f'<button class="vote" data-favorite="{r["id"]}" aria-pressed="false">☆ Garder en favori</button><details><summary>Enregistrement et crédits</summary><p>{html.escape(r["recordingNote"])}</p><p><a href="{html.escape(r["sourceUrl"],quote=True)}" target="_blank" rel="noopener">Source de l’enregistrement</a> · '
 page+=f'<a href="{html.escape(r["licenseUrl"],quote=True)}">{html.escape(r["license"])}</a>' if r['licenseUrl'] else html.escape(r['license'])
 page+='<p>Extraits raccourcis, volume harmonisé et fondus ajoutés. Les licences indiquées s’appliquent aux extraits correspondants.</p></details></article>'
page+='</section><footer>Sampler autonome : les extraits sont inclus dans cette page et se lisent sans connexion. Les versions de 24 secondes sont retenues pour une rotation aléatoire entre les parties.</footer></main>'
page+='<script>const tracks='+json.dumps([{k:r[k] for k in ['id','title','composer']} for r in rows],ensure_ascii=False)+';'
page+='''let active=null,queue=[],current=null;const now=document.querySelector('#now'),podium=document.querySelector('#podium');function stop(){queue=[];document.querySelectorAll('audio').forEach(a=>{a.pause();a.currentTime=0});document.querySelectorAll('article').forEach(a=>a.classList.remove('active'));active=null;current=null;podium.classList.remove('playing');document.querySelector('#progress').value=0;now.textContent='Écoute arrêtée.'}async function play(id,kind,automatic=false){if(!automatic)queue=[];document.querySelectorAll('audio').forEach(a=>{a.pause();a.currentTime=0});document.querySelectorAll('article').forEach(a=>a.classList.remove('active'));active=document.querySelector('#audio-'+id+'-'+kind);current=tracks.find(t=>t.id===id);document.querySelector('#card-'+id).classList.add('active');podium.classList.remove('playing');void podium.offsetWidth;podium.classList.add('playing');now.textContent=current.composer+' · '+current.title+' · '+(kind==='short'?'12':'24')+' s';try{await active.play()}catch(e){now.textContent='La lecture a été bloquée. Cliquez de nouveau sur Écouter.';queue=[];podium.classList.remove('playing')}}document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>play(b.dataset.id,b.dataset.kind));document.querySelector('#stop').onclick=stop;document.querySelector('#all').onclick=()=>{stop();const kind=document.querySelector('#length').value;queue=tracks.map(t=>[t.id,kind]);const next=queue.shift();play(...next,true)};document.querySelectorAll('audio').forEach(a=>{a.ontimeupdate=()=>{if(a===active)document.querySelector('#progress').value=a.currentTime/a.duration||0};a.onended=()=>{if(a!==active)return;if(queue.length){const next=queue.shift();play(...next,true)}else{podium.classList.remove('playing');now.textContent='Écoute terminée.'}}});function winner(){const name=document.querySelector('#name').value.trim()||'Camille';document.querySelector('#winner').textContent=document.querySelector('#tie').checked?'Gagnants : '+name+' et Alex':'Gagnant : '+name}document.querySelector('#name').oninput=winner;document.querySelector('#tie').onchange=winner;let favorites=[];try{favorites=JSON.parse(localStorage.getItem('triviaparty-winner-music-favorites')||'[]')}catch(e){}function stars(){document.querySelectorAll('[data-favorite]').forEach(b=>{const yes=favorites.includes(b.dataset.favorite);b.classList.toggle('voted',yes);b.setAttribute('aria-pressed',String(yes));b.textContent=yes?'★ Favori':'☆ Garder en favori'})}document.querySelectorAll('[data-favorite]').forEach(b=>b.onclick=()=>{const id=b.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];try{localStorage.setItem('triviaparty-winner-music-favorites',JSON.stringify(favorites))}catch(e){}stars()});stars();</script></html>'''
(D/'sampler.html').write_text(page,encoding='utf8')
credits='# Musiques pour le gagnant — sampler\n\nSept options, chacune en 12 et 24 secondes. Ouvrir [le sampler autonome](../build/winner-music/sampler.html). Les extraits sont proposés pour comparaison ; le son du jeu n’a pas été remplacé.\n\n'
for r in rows:
 credits+=f'## {r["composer"]} — {r["title"]}\n\n{r["mood"]}\n\nCrédit : {r["credit"]}\n\nSource : [{r["sourceTitle"]}]({r["sourceUrl"]})\n\nLicence de l’enregistrement indiquée par la source : {r["license"]}'+(f' ([texte]({r["licenseUrl"]}))' if r['licenseUrl'] else '')+'.\n\n'
 for v in r['variants']:credits+=f'- {v["kind"]} : {v["startSeconds"]}–{v["endSeconds"]} s de la source ; {v["durationSeconds"]} s après découpe.\n'
 credits+='\nModifications : découpe, normalisation -18 LUFS / crête -2 dBTP, fondus, export stéréo 44,1 kHz et MP3 160 kb/s.\n\n'
(R/'audio-bank/WINNER-MUSIC-SAMPLER.md').write_text(credits,encoding='utf8')
print('Built offline sampler with 7 pieces / 14 excerpts:',round(len(page)/1024/1024,1),'MB',flush=True)
